<template>
  <section ref="root" class="migration-card" aria-label="Portal onboarding" tabindex="-1">
    <p v-if="loading" role="status">Checking your onboarding steps…</p>
    <p v-if="error" class="step-error" role="alert" tabindex="-1">{{ error }}</p>
    <template v-if="data.enrolled">
      <p class="eyebrow">{{ clientType === 'learning' || clientType === 'tutoring' ? data.profile?.agencyName : 'AuricWell' }} <span>Portal onboarding</span></p>
      <h2>{{ data.profile?.name }}</h2>
      <p v-if="!currentItem">Your available onboarding steps are complete. Thank you for making the move with us.</p>
      <template v-else>
        <p>Thank you for moving with us. Complete one section at a time so your new portal is accurate. Your progress is saved as you finish each step.</p>
        <div class="care-context"><strong>{{ data.profile?.agencyName }}</strong><span v-if="data.profile?.school">SchoolCareBridge · {{ data.profile.school.name }}</span><span v-for="provider in data.profile?.providers || []" :key="provider.id">Your provider: {{ provider.name }}</span></div>
        <nav class="step-track" aria-label="Onboarding progress"><button v-for="(item,index) in actionableItems" :key="item.key" type="button" :class="{current:item.key===currentKey,done:item.complete}" :aria-current="item.key===currentKey?'step':undefined" @click="selectStep(item.key)"><span>{{ item.complete ? '✓' : index+1 }}</span>{{ item.title }}</button></nav>
        <article :key="currentKey" ref="stepPanel" class="step-panel" tabindex="-1" @invalid.capture="highlightInvalid">
          <p class="step-count">Step {{ currentIndex+1 }} of {{ actionableItems.length }}</p><h3>{{ currentItem.title }}</h3><p>{{ currentItem.detail }}</p>
          <GuardianClientDetails v-if="currentKey==='information'" :client-id="Number(clientId)" />
          <FamilyNotificationChoices v-else-if="currentKey==='notifications'" :agency-id="agencyId" :client-id="clientId" @saved="verifyAndContinue" />
          <GuardianPlanProgressPanel v-else-if="currentKey==='plan'" :client-id="clientId" :agency-id="agencyId" :client-type="clientType" />
          <template v-else-if="data.demo && ['insurance','authorization','payment'].includes(currentKey)"><div class="demo-step"><strong>Fictional test profile</strong><p>{{ currentKey==='insurance'?'A real family securely uploads the front and back of their commercial insurance card here.':currentKey==='authorization'?'A real family reviews the payment terms and signs their authorization here.':'A real family adds a card securely or selects a saved card for this profile.' }}</p><p>This example does not upload a real insurance card, sign a financial agreement, or authorize a charge.</p><button type="button" :disabled="busy" @click="completeDemo">Complete with sample information</button></div></template>
          <InsuranceCardTasks v-else-if="currentKey==='insurance'" :agency-id="agencyId" :client-id="clientId" />
          <GuardianPaymentInsuranceTab v-else-if="['authorization','payment'].includes(currentKey)" :agency-id="agencyId" :client-id="clientId" :section="currentKey" />
          <label v-if="currentKey==='information'" class="confirmation" :class="{invalid:confirmationError}"><input ref="confirmationInput" v-model="confirmed" type="checkbox" @change="confirmationError=false"/> I reviewed this profile. Its information is correct, or I submitted the needed corrections.</label>
          <div class="step-actions"><button v-if="currentIndex>0" type="button" @click="selectStep(actionableItems[currentIndex-1].key)">Back</button><button v-if="currentKey!=='notifications'" type="button" :disabled="busy" class="continue" @click="verifyAndContinue">{{ busy?'Checking…':'Save & continue' }}</button></div>
        </article>
      </template>
      <div v-if="!currentItem" class="onboarding-done"><button type="button" @click="$emit('finished')">Open dashboard</button><button type="button" @click="currentKey=actionableItems[0]?.key || ''">Review completed steps</button></div>
      <p v-if="waitingItems.length" class="waiting">Waiting for your care team: {{ waitingItems.map(i=>i.title).join(', ') }}. These steps do not block your portal.</p>
      <p v-if="hasIncomplete" class="reminder-copy">If email updates are enabled, we’ll remind you every 48 hours while available steps remain. You can return through Onboarding in the menu.</p>
      <details><summary>About your move and your information</summary><p>{{ data.historyNotice }}</p><button type="button" @click="$emit('navigate','help')">Learn about your portal</button></details>
    </template>
    <p v-else-if="!loading && !error">No onboarding steps are assigned for this profile.</p>
  </section>
</template>
<script setup>
import {computed,nextTick,ref,watch} from 'vue';import api from '../../services/api';
import GuardianClientDetails from './GuardianClientDetails.vue';import FamilyNotificationChoices from './FamilyNotificationChoices.vue';import GuardianPlanProgressPanel from './GuardianPlanProgressPanel.vue';import GuardianPaymentInsuranceTab from './GuardianPaymentInsuranceTab.vue';import InsuranceCardTasks from '../billing/InsuranceCardTasks.vue';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String],clientType:String,active:Boolean});const emit=defineEmits(['state','navigate','finished']);
const data=ref({}),error=ref(''),loading=ref(false),busy=ref(false),confirmed=ref(false),confirmationError=ref(false),currentKey=ref(''),root=ref(null),stepPanel=ref(null),confirmationInput=ref(null);let seq=0;
const actionableItems=computed(()=>(data.value.items||[]).filter(i=>!i.waiting));const waitingItems=computed(()=>(data.value.items||[]).filter(i=>i.waiting&&!i.complete));const hasIncomplete=computed(()=>actionableItems.value.some(i=>!i.complete));const currentItem=computed(()=>actionableItems.value.find(i=>i.key===currentKey.value));const currentIndex=computed(()=>actionableItems.value.findIndex(i=>i.key===currentKey.value));
async function scrollStep(){await nextTick();const target=stepPanel.value||root.value;target?.scrollIntoView?.({block:'start',behavior:'instant'});target?.focus?.({preventScroll:true});}
function selectStep(key){currentKey.value=key;error.value='';confirmationError.value=false;confirmed.value=false;scrollStep();}
async function refresh(own){const r=await api.get(`/portal-migration/clients/${props.clientId}`,{params:{agencyId:props.agencyId}});if(own!==seq)return false;data.value=r.data;emit('state',r.data);return true;}
async function load(){const own=++seq;data.value={};currentKey.value='';error.value='';confirmed.value=false;emit('state',null);if(!props.agencyId||!props.clientId)return;loading.value=true;try{if(await refresh(own))currentKey.value=actionableItems.value.find(i=>!i.complete)?.key||'';}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'Your onboarding steps could not be loaded.';}finally{if(own===seq)loading.value=false;}}
function highlightInvalid(event){event.target?.classList.add('onboarding-field-error');event.target?.scrollIntoView?.({block:'center'});event.target?.focus?.();}
async function verifyAndContinue(){if(busy.value)return;if(currentKey.value==='information'&&!currentItem.value?.complete&&!confirmed.value){confirmationError.value=true;error.value='Please review the information and check the confirmation below.';await nextTick();confirmationInput.value?.scrollIntoView?.({block:'center'});confirmationInput.value?.focus();return;}const own=seq,key=currentKey.value;busy.value=true;error.value='';try{if(key==='information'&&!currentItem.value.complete)await api.post(`/portal-migration/clients/${props.clientId}/information`,{agencyId:props.agencyId,confirmed:true,revision:data.value.informationRevision});if(!await refresh(own))return;const item=data.value.items.find(i=>i.key===key);if(item&&!item.complete&&!item.waiting){error.value='This section is not complete yet. Finish the action above, then continue.';const invalid=stepPanel.value?.querySelector(':invalid');if(invalid)highlightInvalid({target:invalid});else{await nextTick();root.value?.querySelector('[role=alert]')?.focus();root.value?.querySelector('[role=alert]')?.scrollIntoView?.({block:'center'});}return;}selectStep(actionableItems.value.find(i=>!i.complete)?.key||'');}catch(e){if(own===seq){error.value=e.response?.data?.error?.message||'Your progress could not be saved. Please try again.';await nextTick();root.value?.querySelector('[role=alert]')?.scrollIntoView?.({block:'center'});}}finally{busy.value=false;}}
async function completeDemo(){if(busy.value)return;busy.value=true;error.value='';const own=seq;try{await api.post(`/portal-migration/clients/${props.clientId}/demo-step`,{agencyId:props.agencyId,step:currentKey.value});if(await refresh(own))selectStep(actionableItems.value.find(i=>!i.complete)?.key||'');}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The sample step could not be completed.';}finally{busy.value=false;}}
watch(()=>[props.agencyId,props.clientId],load,{immediate:true});watch(()=>props.active,active=>{if(active)scrollStep();});
</script>
<style scoped>
.migration-card{padding:24px;border:1px solid #d6e3ef;border-radius:16px;background:white;color:#173451;outline:none;scroll-margin-top:165px}.eyebrow{font-size:12px;font-weight:700;color:#2467a7}.eyebrow span{margin-left:8px;color:#52647c}.migration-card h2{margin:8px 0;font-size:24px}.migration-card p{line-height:1.6}.care-context{display:grid;gap:5px;padding:14px;background:#f2f7fb;border-radius:10px;font-size:13px}.step-track{display:flex;gap:8px;overflow-x:auto;margin:20px 0;padding-bottom:6px}.step-track button{flex:0 0 auto;max-width:175px;text-align:left;font-size:12px;background:white;color:#52647c;border:1px solid #d6e3ef;padding:10px;border-radius:8px}.step-track button span{display:inline-grid;place-items:center;width:22px;height:22px;margin-right:5px;border-radius:50%;background:#eef3f8}.step-track .current{color:#16457c;border-color:#2467a7;background:#f0f6ff}.step-track .done span{background:#e3f2e9;color:#236342}.step-panel{padding:22px;border:1px solid #b9cfe6;border-top:4px solid #2467a7;border-radius:12px;outline:none;scroll-margin-top:170px}.step-panel h3{font-size:21px;margin:7px 0}.step-count{font-size:12px;color:#52647c}.step-actions,.onboarding-done{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.migration-card button{font-family:inherit;cursor:pointer}.step-actions button,.onboarding-done button,.demo-step button,details button{padding:12px 18px;border:1px solid #bacfe3;background:white;color:#16457c;border-radius:9px}.step-actions .continue,.onboarding-done button:first-child,.demo-step button{background:#16457c;color:white}.confirmation{display:flex;gap:10px;align-items:start;border:1px solid transparent;border-radius:8px;padding:12px;margin-top:15px}.confirmation input{width:20px;height:20px;flex-shrink:0}.confirmation.invalid,.step-panel :deep(.onboarding-field-error){outline:2px solid #b42318;background:#fff4f2}.step-error{padding:14px;background:#fff0ed;color:#a12727;border-radius:8px;scroll-margin-top:170px}.waiting,.reminder-copy{font-size:13px;color:#52647c}.demo-step{padding:18px;background:#f3f6fb;border-radius:10px}details{margin-top:20px;font-size:13px}@media(max-width:560px){.migration-card{padding:16px}.step-panel{padding:14px}.step-track button{max-width:140px}.step-panel :deep(.detail-grid){grid-template-columns:1fr}}
</style>
